#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <thread>
#include <algorithm>

static int N;

struct Result {
    int maxflips;
    long checksum;
};

// factorial table
static long fact[32];

void work(long start, long end, Result* res) {
    int perm[32], count[32], tperm[32];

    // Generate the permutation at index 'start' using factorial number system
    long idx = start;
    int fperm[32];
    for (int i = 0; i < N; i++) fperm[i] = i;
    for (int i = N - 1; i >= 0; i--) {
        long d = idx / fact[i];
        idx = idx % fact[i];
        count[i] = (int)d;
        // rotate: take element at position d and move to front-ish
        int chosen = fperm[d];
        for (int j = d; j > 0; j--) fperm[j] = fperm[j-1];
        // Actually we need the standard fannkuch permutation generation.
        // Reset approach below.
        (void)chosen;
    }

    // Use standard incremental permutation generation as in benchmark.
    // Re-initialize perm from count using the algorithm.
    for (int i = 0; i < N; i++) perm[i] = i;
    // apply rotations according to count
    for (int i = N - 1; i > 0; i--) {
        // rotate first i+1 elements left by count[i]
        int c = count[i];
        for (int r = 0; r < c; r++) {
            int t = perm[0];
            for (int j = 0; j < i; j++) perm[j] = perm[j+1];
            perm[i] = t;
        }
    }

    int maxflips = 0;
    long checksum = 0;

    for (long pidx = start; pidx < end; pidx++) {
        // count flips
        if (perm[0] != 0) {
            memcpy(tperm, perm, N * sizeof(int));
            int flips = 0;
            int first = tperm[0];
            do {
                // reverse tperm[0..first]
                int lo = 0, hi = first;
                while (lo < hi) {
                    int t = tperm[lo]; tperm[lo] = tperm[hi]; tperm[hi] = t;
                    lo++; hi--;
                }
                flips++;
                first = tperm[0];
            } while (first != 0);

            if (flips > maxflips) maxflips = flips;
            checksum += (pidx & 1) ? -flips : flips;
        }

        // generate next permutation (incremental)
        // standard algorithm
        int first = perm[0];
        for (int i = 0; i < N - 1; ) {
            // rotate left by one the first i+2 elements
            int next = perm[1];
            perm[0] = next;
            for (int j = 1; j <= i; j++) perm[j] = perm[j+1];
            perm[i+1] = first;
            first = next; // not used after

            count[i]++;
            if (count[i] <= i) break;
            count[i] = 0;
            i++;
            first = perm[0];
        }
    }

    res->maxflips = maxflips;
    res->checksum = checksum;
}

int main(int argc, char** argv) {
    N = (argc > 1) ? atoi(argv[1]) : 11;
    if (N < 1) N = 1;

    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i;

    long total = fact[N];

    unsigned hw = std::thread::hardware_concurrency();
    int nthreads = hw ? (int)hw : 4;
    if ((long)nthreads > total) nthreads = (int)total;
    if (nthreads < 1) nthreads = 1;

    std::vector<Result> results(nthreads);
    std::vector<std::thread> threads;

    long chunk = total / nthreads;
    long rem = total % nthreads;
    long cur = 0;
    for (int t = 0; t < nthreads; t++) {
        long sz = chunk + (t < rem ? 1 : 0);
        long s = cur;
        long e = cur + sz;
        cur = e;
        threads.emplace_back(work, s, e, &results[t]);
    }
    for (auto& th : threads) th.join();

    int maxflips = 0;
    long checksum = 0;
    for (auto& r : results) {
        if (r.maxflips > maxflips) maxflips = r.maxflips;
        checksum += r.checksum;
    }

    printf("%ld\nPfannkuchen(%d) = %d\n", checksum, N, maxflips);
    return 0;
}
