int main(int argc, char** argv) {
    int n = 27;
    if (argc > 1) n = atoi(argv[1]);

    mpz_t tmp1, tmp2, acc, den, num;
    mpz_init(tmp1);
    mpz_init(tmp2);
    mpz_init_set_ui(acc, 0);
    mpz_init_set_ui(den, 1);
    mpz_init_set_ui(num, 1);

    unsigned long k = 0;
    int i = 0;
    char buf[16];
    int col = 0;

    auto extract = [&](unsigned long x) -> unsigned long {
        // (num*x + acc) / den
        mpz_mul_ui(tmp1, num, x);
        mpz_add(tmp1, tmp1, acc);
        mpz_tdiv_q(tmp1, tmp1, den);
        return mpz_get_ui(tmp1);
    };

    while (i < n) {
        // next term
        k++;
        unsigned long k2 = k * 2 + 1;
        mpz_mul_2exp(acc, acc, 1); // acc *= 2 (since num contributes)
        mpz_addmul_ui(acc, num, 2); // acc += num*2
        mpz_mul_ui(acc, acc, 1);
        // Actually use standard algorithm below
        break;
    }

    // Reset and use proper Gibbons spigot
    mpz_set_ui(acc, 0);
    mpz_set_ui(den, 1);
    mpz_set_ui(num, 1);
    k = 0;
    i = 0;
    col = 0;

    while (i < n) {
        k++;
        // num2 = num*k; acc2=(acc+num*2)*(2k+1); den2=den*(2k+1)
        unsigned long k2 = 2 * k + 1;
        mpz_addmul_ui(acc, num, 2);
        mpz_mul_ui(acc, acc, k2);
        mpz_mul_ui(den, den, k2);
        mpz_mul_ui(num, num, k);

        // check if we can extract a digit
        if (mpz_cmp(num, acc) > 0) continue;

        unsigned long d3 = extract(3);
        unsigned long d4 = extract(4);
        if (d3 != d4) continue;

        // emit digit d3
        putchar('0' + (int)d3);
        i++;
        col++;
        if (col == 10) {
            printf("\t:%d\n", i);
            col = 0;
        }

        // acc = (acc - den*d) * 10; num *= 10; den *= 10
        mpz_submul_ui(acc, den, d3);
        mpz_mul_ui(acc, acc, 10);
        mpz_mul_ui(num, num, 10);
    }

    if (col != 0) {
        for (int j = col; j < 10; j++) putchar(' ');
        printf("\t:%d\n", n);
    }

    mpz_clear(tmp1);
    mpz_clear(tmp2);
    mpz_clear(acc);
    mpz_clear(den);
    mpz_clear(num);
    return 0;
}
