#include <cstdio>
#include <string>
#include <vector>
#include <thread>
#include <unistd.h>
#include <pcre.h>

static std::string readAll() {
    std::string data;
    data.reserve(1 << 20);
    char buf[1 << 16];
    ssize_t n;
    while ((n = read(0, buf, sizeof(buf))) > 0)
        data.append(buf, n);
    return data;
}

struct Regex {
    pcre *re;
    pcre_extra *extra;
    Regex(const char *pat) {
        const char *err;
        int erroff;
        re = pcre_compile(pat, 0, &err, &erroff, nullptr);
        extra = pcre_study(re, 0, &err);
    }
    int count(const std::string &s) const {
        int cnt = 0;
        int ov[3];
        int pos = 0;
        int len = (int)s.size();
        while (pos <= len) {
            int rc = pcre_exec(re, extra, s.data(), len, pos, 0, ov, 3);
            if (rc < 0) break;
            cnt++;
            pos = ov[1];
            if (ov[0] == ov[1]) pos++;
        }
        return cnt;
    }
    std::string replaceAll(const std::string &s, const std::string &rep) const {
        std::string out;
        out.reserve(s.size());
        int ov[3];
        int pos = 0;
        int len = (int)s.size();
        while (pos <= len) {
            int rc = pcre_exec(re, extra, s.data(), len, pos, 0, ov, 3);
            if (rc < 0) {
                out.append(s, pos, len - pos);
                break;
            }
            out.append(s, pos, ov[0] - pos);
            out.append(rep);
            pos = ov[1];
            if (ov[0] == ov[1]) {
                if (pos < len) out.push_back(s[pos]);
                pos++;
            }
        }
        return out;
    }
};

int main(int argc, char **argv) {
    std::string input = readAll();
    size_t originalLen = input.size();

    Regex strip(">.*\\n|\\n");
    std::string seq = strip.replaceAll(input, "");
    size_t strippedLen = seq.size();

    const char *patterns[9] = {
        "agggtaaa|tttaccct",
        "[cgt]gggtaaa|tttaccc[acg]",
        "a[act]ggtaaa|tttacc[agt]t",
        "ag[act]gtaaa|tttac[agt]ct",
        "agg[act]taaa|ttta[agt]cct",
        "aggg[acg]aaa|ttt[cgt]ccct",
        "agggt[cgt]aa|tt[acg]accct",
        "agggta[cgt]a|t[acg]taccct",
        "agggtaa[cgt]|[acg]ttaccct"
    };

    std::vector<int> counts(9);
    std::vector<std::thread> threads;
    for (int i = 0; i < 9; i++) {
        threads.emplace_back([&, i]() {
            Regex r(patterns[i]);
            counts[i] = r.count(seq);
        });
    }
    for (auto &t : threads) t.join();

    struct Sub { const char *pat; const char *rep; };
    Sub subs[5] = {
        {"tHa[Nt]", "<4>"},
        {"aND|caN|Ha[DS]|WaS", "<3>"},
        {"a[NSt]|BY", "<2>"},
        {"<[^>]*>", "|"},
        {"\\|[^|][^|]*\\|", "-"}
    };

    std::string cur = seq;
    for (int i = 0; i < 5; i++) {
        Regex r(subs[i].pat);
        cur = r.replaceAll(cur, subs[i].rep);
    }
    size_t finalLen = cur.size();

    std::string out;
    for (int i = 0; i < 9; i++) {
        out += patterns[i];
        out += ' ';
        out += std::to_string(counts[i]);
        out += '\n';
    }
    out += '\n';
    out += std::to_string(originalLen);
    out += '\n';
    out += std::to_string(strippedLen);
    out += '\n';
    out += std::to_string(finalLen);
    out += '\n';

    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
