#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
#include <cstring>

// Node-based tree using an arena for fast allocation per subtree
struct Node {
    Node* left;
    Node* right;
};

// Arena allocator
struct Arena {
    std::vector<char*> blocks;
    size_t blockSize;
    size_t offset;
    char* current;

    Arena(size_t bs = 1 << 20) : blockSize(bs), offset(0), current(nullptr) {}

    ~Arena() {
        for (char* b : blocks) free(b);
    }

    Node* alloc() {
        if (!current || offset + sizeof(Node) > blockSize) {
            current = (char*)malloc(blockSize);
            blocks.push_back(current);
            offset = 0;
        }
        Node* n = (Node*)(current + offset);
        offset += sizeof(Node);
        return n;
    }
};

Node* makeTree(int depth, Arena& arena) {
    Node* n = arena.alloc();
    if (depth > 0) {
        n->left = makeTree(depth - 1, arena);
        n->right = makeTree(depth - 1, arena);
    } else {
        n->left = nullptr;
        n->right = nullptr;
    }
    return n;
}

long checkTree(Node* n) {
    if (!n->left) return 1;
    return 1 + checkTree(n->left) + checkTree(n->right);
}

int main(int argc, char** argv) {
    int N = 18;
    if (argc > 1) N = atoi(argv[1]);

    int minDepth = 4;
    int maxDepth = (N > minDepth + 2) ? N : minDepth + 2;
    int stretchDepth = maxDepth + 1;

    // Stretch tree
    {
        Arena arena;
        Node* stretch = makeTree(stretchDepth, arena);
        long c = checkTree(stretch);
        printf("stretch tree of depth %d\t check: %ld\n", stretchDepth, c);
    }

    // Long-lived tree
    Arena longLivedArena;
    Node* longLivedTree = makeTree(maxDepth, longLivedArena);

    // Prepare output buffer for depth groups (ordered)
    std::vector<std::string> results;

    for (int depth = minDepth; depth <= maxDepth; depth += 2) {
        long iterations = 1L << (maxDepth - depth + minDepth);
        long check = 0;
        for (long i = 0; i < iterations; ++i) {
            Arena arena(1 << 16);
            Node* t = makeTree(depth, arena);
            check += checkTree(t);
        }
        char buf[128];
        snprintf(buf, sizeof(buf), "%ld\t trees of depth %d\t check: %ld\n",
                 iterations, depth, check);
        results.push_back(buf);
    }

    for (const auto& s : results) fputs(s.c_str(), stdout);

    long llCheck = checkTree(longLivedTree);
    printf("long lived tree of depth %d\t check: %ld\n", maxDepth, llCheck);

    return 0;
