#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <algorithm>
#include <unordered_map>

static std::string seq;

// encode nucleotides A=0 C=1 G=2 T=3
static inline int code(char c) {
    switch (c) {
        case 'A': return 0;
        case 'C': return 1;
        case 'G': return 2;
        case 'T': return 3;
    }
    return 0;
}

static char decode(int v) {
    static const char m[4] = {'A','C','G','T'};
    return m[v];
}

// count kmers of length k, return map from encoded key -> count
static std::unordered_map<uint64_t,uint64_t> countKmers(int k) {
    std::unordered_map<uint64_t,uint64_t> m;
    m.reserve(1 << (2*k));
    size_t n = seq.size();
    if (n < (size_t)k) return m;
    uint64_t mask = (k*2 >= 64) ? ~0ULL : ((1ULL << (2*k)) - 1);
    uint64_t key = 0;
    for (int i = 0; i < k; i++) key = (key << 2) | code(seq[i]);
    m[key]++;
    for (size_t i = k; i < n; i++) {
        key = ((key << 2) | code(seq[i])) & mask;
        m[key]++;
    }
    return m;
}

static void writeFreq(int k) {
    auto m = countKmers(k);
    uint64_t total = 0;
    for (auto &p : m) total += p.second;
    std::vector<std::pair<uint64_t,uint64_t>> v(m.begin(), m.end());
    std::sort(v.begin(), v.end(), [](const std::pair<uint64_t,uint64_t>&a, const std::pair<uint64_t,uint64_t>&b){
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    for (auto &p : v) {
        std::string s(k, ' ');
        uint64_t key = p.first;
        for (int i = k-1; i >= 0; i--) {
            s[i] = decode(key & 3);
            key >>= 2;
        }
        double pct = total ? (100.0 * (double)p.second / (double)total) : 0.0;
        printf("%s %.3f\n", s.c_str(), pct);
    }
    printf("\n");
}

static void writeCount(const char* frag) {
    int k = (int)strlen(frag);
    auto m = countKmers(k);
    uint64_t key = 0;
    for (int i = 0; i < k; i++) key = (key << 2) | code(frag[i]);
    uint64_t cnt = 0;
    auto it = m.find(key);
    if (it != m.end()) cnt = it->second;
    printf("%llu\t%s\n", (unsigned long long)cnt, frag);
}

int main(int argc, char** argv) {
    (void)argc; (void)argv;

    // read stdin, find THREE section
    std::string all;
    {
        char buf[1 << 16];
        size_t r;
        while ((r = fread(buf, 1, sizeof(buf), stdin)) > 0) {
            all.append(buf, r);
        }
    }

    // find ">THREE"
    size_t pos = all.find(">THREE");
    if (pos == std::string::npos) {
        // maybe input is just the three sequence; take all
        pos = 0;
    } else {
        // skip to end of header line
        pos = all.find('\n', pos);
        if (pos == std::string::npos) pos = all.size();
        else pos++;
    }

    seq.reserve(all.size() - pos);
    for (size_t i = pos; i < all.size(); i++) {
        char c = all[i];
        if (c == '>') break; // next section
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t') continue;
        if (c >= 'a' && c <= 'z') c -= 32;
        seq.push_back(c);
    }

    writeFreq(1);
    writeFreq(2);
    writeCount("GGT");
    writeCount("GGTA");
    writeCount("GGTATT");
    writeCount("GGTATTTTAATT");
    writeCount("GGTATTTTAATTTATAGT");

    return 0;
}
