int main(int argc, char** argv) {
    // N is argv[1] but unused for this benchmark
    (void)argc; (void)argv;

    // Build complement table
    char comp[256];
    for (int i = 0; i < 256; i++) comp[i] = (char)i;
    const char* from = "ACGTUMRWSYKVHDBNacgtumrwsykvhdbn";
    const char* to   = "TGCAAKYWSRMBDHVNTGCAAKYWSRMBDHVN";
    for (int i = 0; from[i]; i++) {
        comp[(unsigned char)from[i]] = to[i];
    }

    // Read all of stdin
    std::vector<char> buf;
    buf.reserve(1 << 20);
    {
        char tmp[1 << 16];
        ssize_t r;
        while ((r = read(0, tmp, sizeof(tmp))) > 0) {
            buf.insert(buf.end(), tmp, tmp + r);
        }
    }
    size_t n = buf.size();
    char* data = buf.data();

    // Output buffer
    std::vector<char> out;
    out.reserve(n + 1024);

    const int LINE = 60;

    size_t i = 0;
    while (i < n) {
        if (data[i] == '>') {
            // header line: copy including newline
            size_t start = i;
            while (i < n && data[i] != '\n') i++;
            if (i < n) i++; // include newline
            out.insert(out.end(), data + start, data + i);

            // collect sequence into a temporary buffer (without newlines)
            std::vector<char> seq;
            while (i < n && data[i] != '>') {
                char c = data[i];
                if (c != '\n' && c != '\r') {
                    seq.push_back(comp[(unsigned char)c]);
                }
                i++;
            }
            // reverse
            size_t len = seq.size();
            for (size_t j = 0; j < len / 2; j++) {
                char t = seq[j];
                seq[j] = seq[len - 1 - j];
                seq[len - 1 - j] = t;
            }
            // write wrapped at 60
            for (size_t j = 0; j < len; j += LINE) {
                size_t end = j + LINE;
                if (end > len) end = len;
                out.insert(out.end(), seq.data() + j, seq.data() + end);
                out.push_back('\n');
            }
        } else {
            // skip stray line
            while (i < n && data[i] != '\n') i++;
            if (i < n) i++;
        }
    }

    // write output
    size_t written = 0;
    while (written < out.size()) {
        ssize_t w = write(1, out.data() + written, out.size() - written);
        if (w <= 0) break;
        written += w;
    }
    return 0;
}
