#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <thread>

static inline double A(int i, int j) {
    long long s = (long long)(i + j) * (i + j + 1) / 2 + i + 1;
    return 1.0 / (double)s;
}

static int N;

static void mult_Av(const std::vector<double>& v, std::vector<double>& out, int start, int end) {
    for (int i = start; i < end; ++i) {
        double sum = 0.0;
        for (int j = 0; j < N; ++j) sum += A(i, j) * v[j];
        out[i] = sum;
    }
}

static void mult_Atv(const std::vector<double>& v, std::vector<double>& out, int start, int end) {
    for (int i = start; i < end; ++i) {
        double sum = 0.0;
        for (int j = 0; j < N; ++j) sum += A(j, i) * v[j];
        out[i] = sum;
    }
}

static void mult_AtAv(const std::vector<double>& v, std::vector<double>& out, std::vector<double>& tmp, int nthreads) {
    std::vector<std::thread> threads;
    int chunk = (N + nthreads - 1) / nthreads;
    for (int t = 0; t < nthreads; ++t) {
        int s = t * chunk, e = std::min(N, s + chunk);
        if (s < e) threads.emplace_back(mult_Av, std::cref(v), std::ref(tmp), s, e);
    }
    for (auto& th : threads) th.join();
    threads.clear();
    for (int t = 0; t < nthreads; ++t) {
        int s = t * chunk, e = std::min(N, s + chunk);
        if (s < e) threads.emplace_back(mult_Atv, std::cref(tmp), std::ref(out), s, e);
    }
    for (auto& th : threads) th.join();
}

int main(int argc, char** argv) {
    N = 4000;
    if (argc > 1) N = atoi(argv[1]);

    std::vector<double> u(N, 1.0), v(N, 0.0), tmp(N, 0.0);

    int nthreads = std::thread::hardware_concurrency();
    if (nthreads < 1) nthreads = 1;

    for (int i = 0; i < 10; ++i) {
        mult_AtAv(u, v, tmp, nthreads);
        mult_AtAv(v, u, tmp, nthreads);
    }

    double vBv = 0.0, vv = 0.0;
    for (int i = 0; i < N; ++i) {
        vBv += u[i] * v[i];
        vv += v[i] * v[i];
    }

    printf("%.9f\n", std::sqrt(vBv / vv));
    return 0;
}
